#include <iostream>
#include <string>
using namespace std;

string check(int guess, int target) {
    if (guess < target) {
        return "太小啦喵";
    } else if (guess > target) {
        return "太大啦喵";
    } else {
        return "猜中啦喵";
    }
}

int main() {
    cout << check(10, 42) << endl;
    cout << check(50, 42) << endl;
    cout << check(42, 42) << endl;
    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int target = 42;
    int picks[4] = {10, 50, 25, 42};
    int i = 0;

    while (true) {
        int guess = picks[i];
        i = i + 1;
        cout << "本喵报 " << guess << endl;
        if (guess == target) {
            cout << "猜中啦喵" << endl;
            break;
        }
    }
    return 0;
}
